    /** @author MC */
    @FunctionalInterface private interface MCDialogCheck {void mcCheck(DialogPane mcPane)throws Exception;}
    private static AtomicReference<Throwable> mcAnswerDialog(ButtonType mcAnswer,MCDialogCheck mcCheck){AtomicReference<Throwable> mcProblem=new AtomicReference<>();Platform.runLater(()->{DialogPane mcPane=mcDialogPane();try{mcCheck.mcCheck(mcPane);}catch(Throwable mcE){mcProblem.set(mcE);}finally{((Button)mcPane.lookupButton(mcAnswer)).fire();}});return mcProblem;}
    private static DialogPane mcDialogPane(){return javafx.stage.Window.getWindows().stream().filter(javafx.stage.Window::isShowing).map(mcW->mcW.getScene().getRoot()).filter(mcP->mcP instanceof DialogPane).map(mcP->(DialogPane)mcP).findFirst().orElseThrow();}
    private static Object mcJs(MCStudioWindow mcWindow,String mcScript)throws Exception{return ((javafx.scene.web.WebView)mcValue(mcWindow,"mcRichEditor")).getEngine().executeScript(mcScript);}
    private static void mcAwaitEditor(MCStudioWindow mcWindow)throws Exception{mcAwaitJs(mcWindow,"typeof window.mcStudio!=='undefined'",true);}
    private static void mcAwaitJs(MCStudioWindow mcWindow,String mcCondition)throws Exception{mcAwaitJs(mcWindow,mcCondition,false);}
    private static void mcAwaitJs(MCStudioWindow mcWindow,String mcCondition,boolean mcRequireReady)throws Exception{
        long mcDeadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(15);while(System.nanoTime()<mcDeadline){if(mcFx(()->(!mcRequireReady||Boolean.TRUE.equals(mcValue(mcWindow,"mcEditorReady")))&&Boolean.TRUE.equals(mcJs(mcWindow,mcCondition))))return;Thread.sleep(25);}throw new AssertionError("El editor no alcanzó el estado esperado: "+mcCondition);
    }

    private static VBox mcFormCard(Node mcInput){Node mcNode=mcInput;while(mcNode!=null&&!mcNode.getStyleClass().contains("binding-card"))mcNode=mcNode.getParent();assertThat(mcNode).isInstanceOf(VBox.class);return (VBox)mcNode;}
    private static List<String> mcButtonLabels(javafx.scene.Parent mcPage){return mcPage.lookupAll(".button").stream().filter(mcN->mcN instanceof Button).map(mcN->((Button)mcN).getText()).toList();}
    private static void mcUpdateCell(ListCell<MCTemplate> mcCell,MCTemplate mcValue)throws Exception{Method mcMethod=mcCell.getClass().getDeclaredMethod("updateItem",MCTemplate.class,boolean.class);mcMethod.setAccessible(true);mcMethod.invoke(mcCell,mcValue,false);}

    private static Scene mcScene(MCStudioWindow mcWindow){Scene mcScene=new Scene(mcWindow.mcRoot(),1280,800);for(String mcFile:List.of("/css/app.css","/css/studio.css"))mcScene.getStylesheets().add(MCTemplateCatalogUiTest.class.getResource(mcFile).toExternalForm());return mcScene;}
    private static MCTemplate mcTemplate(MCDocumentStore mcStore,String mcName,String mcText)throws Exception{try(XWPFDocument mcDocument=new XWPFDocument()){mcDocument.createParagraph().createRun().setText(mcText);byte[] mcBytes=MCDocumentEngine.mcBytes(mcDocument);return mcStore.mcSaveTemplate(new MCTemplate(0,mcName,mcBytes,mcBytes));}}
    private static void mcSnapshotConfigured(MCStudioWindow mcWindow,String mcName)throws Exception{
        if(System.getProperty("studio.ui.snapshots")==null)return;
        Node mcPage=((StackPane)mcValue(mcWindow,"mcWorkspace")).getChildren().get(0);mcPage.setOpacity(1);mcPage.setTranslateY(0);
        for(boolean mcDark:List.of(false,true)){Application.setUserAgentStylesheet(mcDark?new PrimerDark().getUserAgentStylesheet():new PrimerLight().getUserAgentStylesheet());mcWindow.mcRoot().applyCss();mcWindow.mcRoot().layout();mcSnapshot(mcWindow,mcName+(mcDark?"-dark":"-light"));}Application.setUserAgentStylesheet(new PrimerLight().getUserAgentStylesheet());
    }
    private static void mcSnapshot(MCStudioWindow mcWindow,String mcName)throws Exception{
        String mcDirectory=System.getProperty("studio.ui.snapshots");if(mcDirectory==null)return;
        javafx.scene.image.WritableImage mcPixels=mcWindow.mcRoot().snapshot(null,null);java.awt.image.BufferedImage mcImage=new java.awt.image.BufferedImage((int)mcPixels.getWidth(),(int)mcPixels.getHeight(),java.awt.image.BufferedImage.TYPE_INT_ARGB);
        for(int mcY=0;mcY<mcImage.getHeight();mcY++)for(int mcX=0;mcX<mcImage.getWidth();mcX++)mcImage.setRGB(mcX,mcY,mcPixels.getPixelReader().getArgb(mcX,mcY));Path mcPath=Path.of(mcDirectory);Files.createDirectories(mcPath);javax.imageio.ImageIO.write(mcImage,"png",mcPath.resolve(mcName+".png").toFile());
    }
    private static <T> T mcFx(Callable<T> mcAction)throws Exception{CompletableFuture<T> mcResult=new CompletableFuture<>();Platform.runLater(()->{try{mcResult.complete(mcAction.call());}catch(Throwable mcE){mcResult.completeExceptionally(mcE);}});return mcResult.get(30,TimeUnit.SECONDS);}
    private static Object mcInvoke(Object mcTarget,String mcName)throws Exception{return mcInvoke(mcTarget,mcName,new Class<?>[0]);}
    private static Object mcInvoke(Object mcTarget,String mcName,Class<?>[] mcTypes,Object...mcArgs)throws Exception{Method mcMethod=mcTarget.getClass().getDeclaredMethod(mcName,mcTypes);mcMethod.setAccessible(true);return mcMethod.invoke(mcTarget,mcArgs);}
    @SuppressWarnings("unchecked") private static <T> T mcValue(Object mcTarget,String mcName)throws Exception{Field mcField=mcTarget.getClass().getDeclaredField(mcName);mcField.setAccessible(true);return (T)mcField.get(mcTarget);}
